//! ML-KEM-768 的 NIST ACVP 向量测试（M8.3）——**程序化生成，勿手改**。
//!
//! 生成：`tools/extract_mlkem_acvp.py`（用法与出处见该脚本头注释）。
//! 来源：NIST ACVP-Server `gen-val/json-files/ML-KEM-keyGen-FIPS203`
//! 与 `ML-KEM-encapDecap-FIPS203`（internal projection；本文件生成
//! 时所用的镜像副本记录于下）。
//!
//! 子集（ML-KEM-768）：keyGen ×3（d,z → ek,dk）、封装 ×3
//! （ek,m → c,ss）、解封装 ×3（dk,c → ss，含 "modify ciphertext"
//! 隐式拒绝用例，官方期望值即为 J(z‖c)）。
//!
//!
//! 另含负例：封装密钥模校验（§7.2）、篡改密文的隐式拒绝差分、
//! dk 头部哈希校验。

#![allow(clippy::similar_names)]

mod common;

use common::{hex, to_hex};
use ferritls_core::mlkem::{self, Mlkem768Ciphertext, Mlkem768DecapsKey, Mlkem768EncapsKey};

/// 生成时所依据的官方镜像文件指纹（SHA-256，2026-09-13）。
const SOURCE_HASHES: [(&str, &str); 2] = [
    (
        "key-gen.json",
        "0fdca41ed30f49c828af80c73a6424ece3accc1e3430ae14492363aaadeb0e48",
    ),
    (
        "encap-decap.json",
        "4b5afd6c7075b1ffebc099a70dcf907b189daadd42921223127732e3ec83c333",
    ),
];

fn seed32(s: &str) -> [u8; 32] {
    hex(s).try_into().expect("32 bytes")
}

/// keyGen：(d, z) → (ek, dk)（含 2400 字节 dk 解析校验）。
#[test]
fn acvp_keygen() {
    // tcId 26
    {
        let d = seed32("e34a701c4c87582f42264ee422d3c684d97611f2523efe0c998af05056d693dc");
        let z = seed32("a85768f3486bd32a01bf9a8f21ea938e648eae4e5448c34c3eb88820b159eedd");
        let (ek, dk) = mlkem::keypair_from_seed(&d, &z);
        assert_eq!(
            to_hex(ek.as_bytes()),
            "",
            "ek tcId 26"
        );
        assert_eq!(
            to_hex(dk.expose_bytes()),
            "",
            "dk tcId 26"
        );
        assert!(Mlkem768DecapsKey::from_bytes(dk.expose_bytes()).is_ok());
    }
    // tcId 27
    {
        let d = seed32("444f032dd19ae7518c4b35b0732a41dc567845aba8bd7b04a9c413a0cf2de0b5");
        let z = seed32("df0f282411f4a071489a8f618e2ae5aef40131cac5233d6d731522720c2feb1c");
        let (ek, dk) = mlkem::keypair_from_seed(&d, &z);
        assert_eq!(
            to_hex(ek.as_bytes()),
            "",
            "ek tcId 27"
        );
        assert_eq!(
            to_hex(dk.expose_bytes()),
            "",
            "dk tcId 27"
        );
        assert!(Mlkem768DecapsKey::from_bytes(dk.expose_bytes()).is_ok());
    }
    // tcId 28
    {
        let d = seed32("092271d05ca63c60880af404d60bc4bb9539e2ea12969581898d56e0ac9a5a68");
        let z = seed32("5aa6dc620a6e9a60cf19a7b4f0ff805bda8219522a548ee5857c3ff6060c7a2f");
        let (ek, dk) = mlkem::keypair_from_seed(&d, &z);
        assert_eq!(
            to_hex(ek.as_bytes()),
            "",
            "ek tcId 28"
        );
        assert_eq!(
            to_hex(dk.expose_bytes()),
            "",
            "dk tcId 28"
        );
        assert!(Mlkem768DecapsKey::from_bytes(dk.expose_bytes()).is_ok());
    }
}

/// 封装：(ek, m) → (c, ss)（确定性 m；官方期望 k = K = G(m‖H(ek))[..32]）。
#[test]
fn acvp_encapsulation() {
    // tcId 26（reason: no modification）
    {
        let ek = Mlkem768EncapsKey::from_bytes(&hex("")).expect("valid vector");
        let m = seed32("2ce74ad291133518fe60c7df5d251b9d82add48462ff505c6e547e949e6b6bf7");
        let (c, ss) = mlkem::encapsulate_with_seed(&ek, &m).expect("encaps");
        assert_eq!(
            to_hex(c.as_bytes()),
            "",
            "c tcId 26"
        );
        assert_eq!(
            to_hex(ss.expose_bytes()),
            "2696d28e9c61c2a01ce9b1608dcb9d292785a0cd58efb7fe13b1de95f0db55b3",
            "ss tcId 26"
        );
    }
    // tcId 27（reason: no modification）
    {
        let ek = Mlkem768EncapsKey::from_bytes(&hex("")).expect("valid vector");
        let m = seed32("76d04f481e68b2f901ecab58b6369a2cc31a9dcced82a1bbd426be0aee266aee");
        let (c, ss) = mlkem::encapsulate_with_seed(&ek, &m).expect("encaps");
        assert_eq!(
            to_hex(c.as_bytes()),
            "",
            "c tcId 27"
        );
        assert_eq!(
            to_hex(ss.expose_bytes()),
            "44263624052c18e3aa23310697414499f1c0eae45a1060d84eeb65fcdbcb5733",
            "ss tcId 27"
        );
    }
    // tcId 28（reason: no modification）
    {
        let ek = Mlkem768EncapsKey::from_bytes(&hex("")).expect("valid vector");
        let m = seed32("fd3c91294d8c974930b4b6135ab647d4a7885c83fcdcb30cbd38332e14094491");
        let (c, ss) = mlkem::encapsulate_with_seed(&ek, &m).expect("encaps");
        assert_eq!(
            to_hex(c.as_bytes()),
            "",
            "c tcId 28"
        );
        assert_eq!(
            to_hex(ss.expose_bytes()),
            "69b8f091a450890c0dcce0120e9bab05054c7785a797c93b6fa39ff5e0bc5a70",
            "ss tcId 28"
        );
    }
}

/// 解封装（VAL）：dk 在组级；modified ciphertext 的期望 k 即
/// J(z‖c)（隐式拒绝）。
#[test]
fn acvp_decapsulation() {
    let dk = Mlkem768DecapsKey::from_bytes(&hex("")).expect("valid vector");
    // tcId 86（reason: modify ciphertext）
    {
        let c = Mlkem768Ciphertext::from_bytes(&hex("")).expect("valid vector");
        let ss = mlkem::decapsulate(&dk, &c);
        assert_eq!(
            to_hex(ss.expose_bytes()),
            "3d23b10df232a180786f61261e85278251746580bebca6acbad60aef6952be69",
            "ss tcId 86"
        );
    }
    // tcId 87（reason: modify ciphertext）
    {
        let c = Mlkem768Ciphertext::from_bytes(&hex("")).expect("valid vector");
        let ss = mlkem::decapsulate(&dk, &c);
        assert_eq!(
            to_hex(ss.expose_bytes()),
            "1d2dcacec14cbb78fe9e418937835eed088cc0683300c965ef3972081f01c4e9",
            "ss tcId 87"
        );
    }
    // tcId 88（reason: no modification）
    {
        let c = Mlkem768Ciphertext::from_bytes(&hex("")).expect("valid vector");
        let ss = mlkem::decapsulate(&dk, &c);
        assert_eq!(
            to_hex(ss.expose_bytes()),
            "dc5b8888bc1eba5c1969c21164ea43e22e7ac0cd012a2f26cb8c487e69ef7ce4",
            "ss tcId 88"
        );
    }
}

/// 负例：ek 模校验拒绝（d1 = 0x0FFF >= q）、篡改密文走隐式拒绝
/// （≠ 正确 ss）、dk 的 h 校验拒绝。
#[test]
fn negative_cases() {
    // ek 前两字节置 0xFF：首系数 d1 = 0x0FFF = 4095 >= q，模校验必须拒绝
    let mut ek = vec![0u8; 1184];
    ek[0] = 0xff;
    ek[1] = 0xff;
    assert!(Mlkem768EncapsKey::from_bytes(&ek).is_err());

    // 篡改密文：decapsulate 返回隐式拒绝值（与正确 ss 不同、不 panic）
    let d = seed32("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
    let z = seed32("f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff000102030405060708090a0b0c0d0e0f");
    let (ek, dk) = mlkem::keypair_from_seed(&d, &z);
    let m = seed32("010201020102030405060708090a0b0c0d0e0f101112131415161718191a1b1c");
    let (c, ss) = mlkem::encapsulate_with_seed(&ek, &m).expect("encaps");
    let mut bad = *c.as_bytes();
    bad[0] ^= 0x01;
    let bad = Mlkem768Ciphertext::from_bytes(&bad).expect("valid vector");
    let ss2 = mlkem::decapsulate(&dk, &bad);
    assert_ne!(to_hex(ss.expose_bytes()), to_hex(ss2.expose_bytes()));
    // 长度错误
    assert!(Mlkem768DecapsKey::from_bytes(&vec![0u8; 2399]).is_err());
    assert!(Mlkem768Ciphertext::from_bytes(&[0u8; 1]).is_err());
    let _ = SOURCE_HASHES;
}
